const crypto = require('crypto');
let password;
try { password = JSON.parse(query).password; } catch(e) { password = query; }
if (!password) throw new Error('password is required');
const salt = crypto.randomBytes(16).toString('hex');
const hash = crypto.scryptSync(password, salt, 64).toString('hex');
return JSON.stringify({ password_hash: `scrypt$${salt}$${hash}` });

const crypto = require('crypto');
let parsed;
try { parsed = JSON.parse(query); } catch(e) { return JSON.stringify({ match: false, error: 'Must pass JSON: {password, stored_hash}' }); }
const { password, stored_hash } = parsed;
if (!password || !stored_hash) return JSON.stringify({ match: false, error: 'Both password and stored_hash required' });
const [scheme, salt, hash] = String(stored_hash).split('$');
if (scheme !== 'scrypt' || !salt || !/^[0-9a-f]{128}$/.test(hash || '')) return JSON.stringify({ match: false, error: 'Unsupported stored_hash format' });
const expected = Buffer.from(hash, 'hex');
const actual = crypto.scryptSync(password, salt, expected.length);
return JSON.stringify({ match: crypto.timingSafeEqual(actual, expected) });
